base='''<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512"><defs><linearGradient id="tile" x1="0" y1="0" x2=".9" y2="1"><stop stop-color="#a88aff"/><stop offset=".44" stop-color="#805bfa"/><stop offset="1" stop-color="#5734ca"/></linearGradient><linearGradient id="shine" x1="0" y1="0" x2="0" y2="1"><stop stop-color="white" stop-opacity=".26"/><stop offset="1" stop-color="white" stop-opacity="0"/></linearGradient><linearGradient id="white" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#e8ddff"/></linearGradient><linearGradient id="mint" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ccfff2"/><stop offset="1" stop-color="#8de1d7"/></linearGradient><filter id="shadow" x="-40%" y="-40%" width="180%" height="190%"><feDropShadow dx="0" dy="12" stdDeviation="10" flood-color="#32147a" flood-opacity=".23"/></filter></defs><rect x="24" y="24" width="464" height="464" rx="116" fill="url(#tile)"/><rect x="27" y="27" width="458" height="458" rx="113" fill="none" stroke="#fff" stroke-opacity=".24" stroke-width="3"/><path d="M143 25H370Q488 25 488 143V213Q330 133 24 245V143Q24 25 143 25Z" fill="url(#shine)"/>%s</svg>'''
icons={
'cw-signature':'''<g filter="url(#shadow)" fill="url(#white)"><path d="M190 166Q190 154 202 151L354 117Q368 114 368 129V319H336V192L222 217V354H190Z"/><path d="M213 177L345 147V174L213 204Z"/><ellipse cx="178" cy="356" rx="45" ry="33" transform="rotate(-18 178 356)"/><ellipse cx="324" cy="321" rx="45" ry="33" transform="rotate(-18 324 321)"/></g><circle cx="388" cy="121" r="13" fill="url(#mint)"/>''',
'cw-vocal':'''<path d="M371 151A153 153 0 1 0 371 361" fill="none" stroke="#fff" stroke-opacity=".23" stroke-width="24" stroke-linecap="round"/><g stroke="url(#white)" stroke-width="26" stroke-linecap="round" filter="url(#shadow)"><path d="M145 239V273M197 199V313M249 151V361M301 207V305"/></g><path d="M353 229V283" stroke="#a7f0e5" stroke-width="26" stroke-linecap="round"/>''',
'cw-studio':'''<rect x="119" y="122" width="263" height="277" rx="46" fill="#35118c" fill-opacity=".22" transform="rotate(9 250 260)"/><rect x="107" y="113" width="263" height="277" rx="46" fill="#ede5ff" fill-opacity=".23" transform="rotate(-8 240 250)"/><g filter="url(#shadow)"><rect x="121" y="131" width="270" height="266" rx="46" fill="url(#white)"/><path d="M154 189H359" stroke="#cfbfff" stroke-width="9" stroke-linecap="round"/><circle cx="157" cy="164" r="5" fill="#9d80e5"/><circle cx="174" cy="164" r="5" fill="#bbabdf"/><path d="M227 232Q227 222 237 228L297 264Q306 270 297 276L237 312Q227 318 227 308Z" fill="#7a51e5"/><path d="M167 348H206M220 348H258" stroke="#b09adf" stroke-width="12" stroke-linecap="round"/><path d="M278 348H343" stroke="#73c6b9" stroke-width="12" stroke-linecap="round"/></g>'''
}
for key,glyph in icons.items():(out/(key+'.svg')).write_text(base.replace('%s',glyph),encoding='utf-8')
(out/'manifest.json').write_text(json.dumps({'default':'cw-signature','variants':[{'id':'cw-signature','name':'Signature Note'},{'id':'cw-vocal','name':'Vocal Wave'},{'id':'cw-studio','name':'Studio Layers'}],'sizes':[16,20,24,32,40,48,64,96,128,256]},indent=2),encoding='utf-8')
print(out)
